import json
from pathlib import Path


def load_payload(path):
    """Read a UTF-8 JSON payload from *path*.

    Top-level objects and arrays are legal. Invalid JSON, or a top-level
    null/bool/number/string, raises ValueError.
    """
    if not isinstance(path, Path):
        path = Path(path)
    try:
        text = path.read_text(encoding="utf-8")
    except OSError as exc:
        raise ValueError("cannot read payload: %s" % path) from exc
    try:
        data = json.loads(text)
    except json.JSONDecodeError as exc:
        raise ValueError("invalid JSON payload: %s" % path) from exc
    if not isinstance(data, (dict, list)):
        raise ValueError("top-level payload must be object or array: %s" % path)
    return data

