import json
import math


def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _is_finite_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v)


def _non_empty_str(v):
    return isinstance(v, str) and v.strip() != ""


def _unwrap(payload):
    """Unwrap an upstream component envelope when present.

    A local object is used directly; only a dict whose key set is exactly
    {"name", "result"} is treated as a component envelope.
    """
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        return payload["result"]
    return payload


def _normalize_event(event):
    if not isinstance(event, dict):
        raise ValueError("each event must be an object")

    # id: required, non-empty string, stripped.
    if "id" not in event:
        raise ValueError("event missing id")
    raw_id = event["id"]
    if not _non_empty_str(raw_id):
        raise ValueError("event id must be a non-empty string")
    normalized_id = raw_id.strip()

    # revision: defaults to 0, must be a non-bool int >= 0.
    if "revision" in event:
        revision = event["revision"]
        if not _is_int(revision) or revision < 0:
            raise ValueError("event revision must be a non-negative int")
    else:
        revision = 0

    # ts (new) wins over timestamp (legacy); presence is what matters.
    if "ts" in event:
        ts = event["ts"]
    elif "timestamp" in event:
        ts = event["timestamp"]
    else:
        raise ValueError("event missing ts/timestamp")
    if not _is_int(ts) or ts < 0:
        raise ValueError("event ts must be a non-negative int")

    # key (new) wins over account (legacy); normalize strip + lowercase.
    if "key" in event:
        key = event["key"]
    elif "account" in event:
        key = event["account"]
    else:
        raise ValueError("event missing key/account")
    if not _non_empty_str(key):
        raise ValueError("event key must be a non-empty string")
    normalized_key = key.strip().lower()

    # value (new) wins over amount (legacy).
    if "value" in event:
        value = event["value"]
    elif "amount" in event:
        value = event["amount"]
    else:
        raise ValueError("event missing value/amount")
    if not _is_finite_number(value):
        raise ValueError("event value must be a finite int/float")

    return {
        "id": normalized_id,
        "revision": revision,
        "ts": ts,
        "key": normalized_key,
        "value": value,
    }


def _parse_event(item):
    if isinstance(item, str):
        try:
            parsed = json.loads(item)
        except json.JSONDecodeError as exc:
            raise ValueError("event JSON string is invalid") from exc
    else:
        parsed = item
    if not isinstance(parsed, dict):
        raise ValueError("each event must be an object or an object JSON string")
    return _normalize_event(parsed)


def transform(payloads, contract):
    """settlement_decode: normalize legacy/new settlement events."""
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    expected = len(contract.get("inputs", []))
    if len(payloads) != expected:
        raise ValueError("payloads count does not match contract inputs")

    raw = _unwrap(payloads[0])
    if not isinstance(raw, dict):
        raise ValueError("settlement input must be an object")
    if "events" not in raw:
        raise ValueError("settlement input missing events")
    events_in = raw["events"]
    if not isinstance(events_in, list):
        raise ValueError("events must be a list")

    events = [_parse_event(item) for item in events_in]
    events.sort(key=lambda e: (e["id"], e["revision"], e["ts"], e["key"], e["value"]))
    return {"name": contract["name"], "result": {"events": events}}

