    if "window_size" not in contract:
        raise ValueError("contract missing window_size")
    window_size = contract["window_size"]
    if not _is_int(window_size) or window_size <= 0:
        raise ValueError("window_size must be a positive int")

    raw = _unwrap(payloads[0])
    if not isinstance(raw, dict):
        raise ValueError("window input must be an object")
    if "events" not in raw:
        raise ValueError("window input missing events")
