    by_id_revision = {}
    for item in events_in:
        event = _normalize_event(item)
        key = (event["id"], event["revision"])
        if key in by_id_revision:
            if by_id_revision[key] != event:
                raise ValueError("conflicting content for same (id, revision)")
            # identical duplicate: drop
        else:
            by_id_revision[key] = event

