        current = latest.get(event["id"])
        if current is None or event["revision"] > current["revision"]:
            latest[event["id"]] = event

    event_count = len(latest)

    groups = {}
    for event in latest.values():
        start = (event["ts"] // window_size) * window_size
        group_key = (start, event["key"])
        groups.setdefault(group_key, []).append(event["value"])

