    for (start, key) in sorted(groups.keys()):
        values = sorted(groups[(start, key)])
        n = len(values)
        p95 = values[math.ceil(0.95 * n) - 1]
        windows.append(
            {
                "start": start,
                "end": start + window_size,
                "key": key,
                "count": n,
                "sum": sum(values),
                "p95": p95,
            }
        )

    return {"name": contract["name"], "result": {"windows": windows, "event_count": event_count}}

