import math


def _is_finite_number(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool) and math.isfinite(v)


def _non_empty_str(v):
    return isinstance(v, str) and v.strip() != ""


def _unwrap(payload):
    if isinstance(payload, dict) and set(payload.keys()) == {"name", "result"}:
        return payload["result"]
    return payload


class _Node:
    __slots__ = ("id", "service", "duration", "error", "parent")

    def __init__(self, node_id, service, duration, error, parent):
        self.id = node_id
        self.service = service
        self.duration = duration
        self.error = error
        self.parent = parent


def _flatten(span, inherited_parent, nodes, seen):
    if not isinstance(span, dict):
        raise ValueError("each span must be an object")

    # id: required, non-empty string, stripped as the node identifier.
    if "id" not in span:
        raise ValueError("span missing id")
    raw_id = span["id"]
    if not _non_empty_str(raw_id):
        raise ValueError("span id must be a non-empty string")
    node_id = raw_id.strip()
    if node_id in seen:
        raise ValueError("duplicate span id: %s" % node_id)
    seen.add(node_id)

    if "service" not in span:
        raise ValueError("span missing service")
    service = span["service"]
    if not _non_empty_str(service):
        raise ValueError("span service must be a non-empty string")

    if "duration" not in span:
        raise ValueError("span missing duration")
    duration = span["duration"]
    if not _is_finite_number(duration) or duration < 0:
        raise ValueError("span duration must be a non-negative finite number")

    if "error" not in span:
        raise ValueError("span missing error")
    error = span["error"]
    if not isinstance(error, bool):
        raise ValueError("span error must be a bool")

    # Explicit parent wins, including explicit null; inherit only when absent.
    if "parent" in span:
        parent = span["parent"]
        if parent is None:
            resolved_parent = None
        elif isinstance(parent, str) and parent.strip() != "":
            resolved_parent = parent.strip()
        else:
            raise ValueError("span parent must be an id or null")
    else:
        resolved_parent = inherited_parent

    nodes.append(_Node(node_id, service, duration, error, resolved_parent))

    if "children" in span:
        children = span["children"]
        if not isinstance(children, list):
            raise ValueError("span children must be a list")
        for child in children:
            _flatten(child, node_id, nodes, seen)


def transform(payloads, contract):
    """trace_correlation: flatten spans and correlate the critical path."""
    if not isinstance(payloads, list):
        raise ValueError("payloads must be a list")
    expected = len(contract.get("inputs", []))
    if len(payloads) != expected:
        raise ValueError("payloads count does not match contract inputs")

    raw = _unwrap(payloads[0])
    if not isinstance(raw, dict):
        raise ValueError("trace input must be an object")
    if "spans" not in raw:
        raise ValueError("trace input missing spans")
    spans_in = raw["spans"]
    if not isinstance(spans_in, list):
        raise ValueError("spans must be a list")

    nodes = []
    seen = set()
    for span in spans_in:
        _flatten(span, None, nodes, seen)

    span_count = len(nodes)

    error_services = sorted(
        {node.service.strip().lower() for node in nodes if node.error}
    )

    if not nodes:
        return {
            "name": contract["name"],
            "result": {
                "error_services": error_services,
                "critical_path": [],
                "duration": 0,
                "span_count": span_count,
            },
        }

    node_ids = {node.id for node in nodes}
    parent_of = {node.id: node.parent for node in nodes}

    for node in nodes:
        if node.parent == node.id:
            raise ValueError("self-loop span id: %s" % node.id)
        if node.parent is not None and node.parent not in node_ids:
            raise ValueError("unknown parent for span: %s" % node.id)

    # Cycle detection over the parent pointers.
    state = {}

    def visit(node_id):
        state[node_id] = 1
        parent = parent_of[node_id]
        if parent is not None:
            pstate = state.get(parent, 0)
            if pstate == 1:
                raise ValueError("cycle detected in span graph")
            if pstate == 0:
                visit(parent)
        state[node_id] = 2

    for node_id in node_ids:
        if node_id not in state:
            visit(node_id)

    children = {node_id: [] for node_id in node_ids}
    for node in nodes:
        if node.parent is not None:
            children[node.parent].append(node.id)

    duration_by_id = {node.id: node.duration for node in nodes}
    roots = [node.id for node in nodes if node.parent is None]

    best_path = None
    best_duration = None

    for root in roots:
        stack = [(root, (root,), duration_by_id[root])]
        while stack:
            node_id, path, total = stack.pop()
            if best_path is None or total > best_duration or (
                total == best_duration and path < best_path
            ):
                best_path = path
                best_duration = total
            for child_id in children[node_id]:
                stack.append(
                    (child_id, path + (child_id,), total + duration_by_id[child_id])
                )

